import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_indexOf_TriageGen2Test {

















    @Test
    public void testIndexOf_PartialMatchFailure() {
        StrBuilder sb = new StrBuilder("ababc");
        // Test the 'continue outer' logic
        // At index 0, 'aba' matches 'aba' but we search for 'abc'
        // index 0: 'aba' vs 'abc' -> mismatch at j=2
        // index 1: 'bab' vs 'abc' -> mismatch at j=0
        // index 2: 'abc' vs 'abc' -> match
        assertEquals(2, sb.indexOf("abc", 0));
    }




}

